choose.when:
(report.reporter_user_id = #{query.userId}
 AND EXISTS (SELECT 1 FROM edu_teacher_class teacher_class
     WHERE teacher_class.teacher_user_id = #{query.userId}
       AND teacher_class.class_organization_id = report.class_organization_id
       AND teacher_class.status = 'ACTIVE'))

mapper.select:
SELECT id, student_id, class_organization_id, reporter_user_id, exception_type,
       content, status, idempotency_key, handled_by, handled_at, version_no, reported_at
FROM edu_exception_report WHERE id = #{id}

mapper.update:
UPDATE edu_exception_report SET status = 'HANDLED', handled_by = #{handledBy},
    handled_at = #{handledAt}, version_no = version_no + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND status = 'SUBMITTED' AND version_no = #{versionNo}

